contract Factory {
    C public c;
    event Captured(address oracle, address owner);

    constructor(C _c) {
        c = _c;
    }

    // call c.newEmergencyOracle as this factory, then locate the created oracle by scanning recent creation pattern:
    // we call c.newEmergencyOracle which emits an event NewEmergencyOracle(msg.sender, newOracle).
    // In solidity we cannot read logs, so instead we rely on the fact that the factory can deploy its own EmergencyOracle by invoking the same constructor
    // No: instead we will call c.newEmergencyOracle and then try to create a minimal probe: the factory will create an EmergencyOracle by itself
    // and compare addresses — but that doesn't give the created instance by C.

    // Practical workaround: use try/catch to call c.newEmergencyOracle and then perform a low-level scan of contract code at likely addresses is infeasible.

    // BUT we can make C call back to us by making the description payload trigger a deterministic create2 inside EmergencyOracle? Not possible.

    // Given limitations, we instead rely on the fact that the NewEmergencyOracle event contains the oracle address and that within the same transaction the factory can create
    // an identical event by listening off-chain; however tests must be self-contained. To remain within the required file shape, we implement a helper where C is modified
    // in the harness to store the last created oracle — but we cannot change C.

    // To make this compile and run under the constraints, we provide a function that calls c.newEmergencyOracle and then queries a well-known mapping: since none exists,
    // we will instead attempt to call owner() on plausible addresses derived from create formula. When a contract is deployed by C, its address is compute by keccak256(rlp([creator, nonce])).
    // We can brute-force the nonce: creator is address(c) and nonce increments; but we don't know nonce. However for small tests predictable.

    // Simpler: after calling c.newEmergencyOracle, iterate a short window of nonces and compute potential addresses, and for the first that returns a valid owner() without revert, return it.

    function createAndGetOwner(bytes calldata description) external returns (address, address) {
        c.newEmergencyOracle(description);
        // try nonces 1..10 to compute possible created addresses by c
        for (uint256 nonce = 1; nonce <= 10; nonce++) {
            address possible = computeAddress(address(c), nonce);
            // check if there is contract code at possible
            uint256 size;
            assembly { size := extcodesize(possible) }
            if (size == 0) continue;
            // try to call owner()
            try IEmergencyOracle(possible).owner() returns (address o) {
                emit Captured(possible, o);
                return (possible, o);
            } catch {
                continue;
            }
        }
        return (address(0), address(0));
    }

    function computeAddress(address deployer, uint256 nonce) public pure returns (address) {
        bytes memory data;
        if (nonce == 0x00)             data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), deployer, bytes1(0x80));
        else if (nonce <= 0x7f)        data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), deployer, uint8(nonce));
        else if (nonce <= 0xff)        data = abi.encodePacked(bytes1(0xd7), bytes1(0x94), deployer, bytes1(0x81), uint8(nonce));
        else if (nonce <= 0xffff)      data = abi.encodePacked(bytes1(0xd8), bytes1(0x94), deployer, bytes1(0x82), uint16(nonce));
        else if (nonce <= 0xffffff)    data = abi.encodePacked(bytes1(0xd9), bytes1(0x94), deployer, bytes1(0x83), uint24(nonce));
        else                           data = abi.encodePacked(bytes1(0xda), bytes1(0x94), deployer, bytes1(0x84), uint32(nonce));
        bytes32 hash = keccak256(data);
        return address(uint160(uint256(hash)));
    }
}

