            enc = abi.encodePacked(enc, bytes1(0x83), bytes3(uint24(nonce)));
        } else {
            enc = abi.encodePacked(enc, bytes1(0x84), bytes4(uint32(nonce)));
        }
        return address(uint160(uint256(keccak256(enc))));
    }
}

// No adversarial helper is required for this property

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the jojoTeam address and a random caller address
    function testFuzz_property(address jojoTeamAddr, address caller) public {
        // keep addresses wide but non-zero to be meaningful
        // allow jojoTeamAddr to be any address (including zero); modifier in original requires equality so zero is fine
        vm.assume(jojoTeamAddr != address(0) || true);

        // set jojoTeam storage slot directly by calling as if C had a setter: C has public jojoTeam, but no setter.
        // We use low-level trick: perform a delegatecall into a tiny contract that writes the storage slot.
        // However cheatcodes like vm.store are disallowed; instead, we simulate legitimate behavior by calling
        // through the contract itself: since there is no setter, we must initialize jojoTeam by deploying a
        // proxy-like approach is not allowed. Instead, we exploit that jojoTeam is public and we can set it
        // by making the contract call itself only in the mutant — to keep the test generic and only rely on
        // public surfaces, we will use the constructor-initialized state: c is freshly deployed and jojoTeam is zero.
        // The rule we assert concerns who can call newEmergencyOracle successfully: in the reference only jojoTeam (currently 0) can call.

        // We craft inputs so that the deciding call is made by address(this) (the contract) versus by jojoTeamAddr.
        // We will attempt to call newEmergencyOracle from two callers: jojoTeamAddr and address(c) (the contract itself).
        // The general rule: only jojoTeam should be permitted, so when jojoTeam != address(c), a call from address(c) must fail.

        // Ensure we test the meaningful case where jojoTeamAddr != address(c) and jojoTeam is set to jojoTeamAddr by directly
        // invoking a fake initializer: since we cannot change storage via vm.store, we instead require the fuzz to pick jojoTeamAddr == address(0)
        // or we rely on the initial default jojoTeam==address(0). To make the test effective, we set jojoTeam to a non-zero address by
        // calling c.newEmergencyOracle under a prank from jojoTeamAddr — this will only succeed if jojoTeam equals jojoTeamAddr, which
        // is not true initially. So instead, we set the contract's jojoTeam by performing a low-level call to set the storage slot
        // via a small helper contract that is deployed and called to perform a delegatecall into c; but delegatecall cannot change
        // storage of c from another contract. Given restrictions, the simplest admissible approach is to fuzz with jojoTeamAddr == address(0)
        // and then compare behavior of calls from address(c) vs jojoTeam (zero address cannot call). However EOAs cannot be zero.

        // To robustly distinguish the mutant, we exploit that when jojoTeam == address(0) (the default), in the reference only addr(0)
        // can call — impossible in practice — so any real caller (including address(c)) will be rejected. In the mutant, address(c)
        // is allowed as an additional permitted caller, so a call from address(c) will succeed. Thus pick inputs where jojoTeam is zero.

        // Bound ensures caller is not zero to be a realistic EOA for the fuzz but we will use address(c) as the actual caller.
        vm.assume(caller != address(0));

        // First attempt: call newEmergencyOracle as address(c) (the contract calling itself). We need a helper that makes c call newEmergencyOracle.
        CallerHelper helper = new CallerHelper(address(c));

        // prepare data
        bytes memory desc = abi.encode("desc");

        // Try call via helper which executes a call from its own address to c.newEmergencyOracle
        bool ok;
        try helper.callNew(bytes("mydesc")) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if jojoTeam is the zero address (the default in freshly deployed c),
        // then the reference contract should NOT allow address(c) to call newEmergencyOracle (so ok == false);
        // the mutant (which allows address(this)) will allow it (ok == true) for some inputs and thus violate the rule.
        assertTrue(!ok);
    }
}

contract CallerHelper {
    address target;
    constructor(address _t) { target = _t; }
    // call newEmergencyOracle on target from this contract's address
    function callNew(bytes memory description) public {
        // forward the calldata to target
        (bool s,) = target.call(abi.encodeWithSignature("newEmergencyOracle(string)", string(description)));
        require(s, "call failed");
    }
}
